// Normalize inputs from the outline webhook. Matches the existing project pattern
// of handling both raw body and {body: {...}} wrap, plus label/name variants.
const input = $input.first().json;
const form = (input && typeof input.body === 'object' && input.body !== null && Object.keys(input.body).length > 0)
  ? input.body
  : input;

const norm = s => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');
const pick = (...keys) => {
  for (const k of keys) {
    if (form[k] !== undefined && form[k] !== null && form[k] !== '') return form[k];
  }
  const targets = keys.map(norm);
  for (const k of Object.keys(form)) {
    const n = norm(k);
    if (targets.some(t => n === t || n.startsWith(t))) return form[k];
  }
  return '';
};

// Keywords can arrive as comma-separated strings or arrays. Normalize to arrays.
const toArr = v => {
  if (Array.isArray(v)) return v.map(x => String(x).trim()).filter(Boolean);
  if (typeof v === 'string') return v.split(/[,;\n]/).map(s => s.trim()).filter(Boolean);
  return [];
};

return [{
  json: {
    input_type: pick('input_type', 'inputType') || 'text',
    text: pick('text', 'client_text', 'clientText') || '',
    audio_base64: pick('audio_base64', 'audioBase64') || '',
    audio_format: pick('audio_format', 'audioFormat') || 'webm',
    focus_keyword: pick('focus_keyword', 'Focus Keyword', 'focusKeyword') || '',
    header_keywords: toArr(pick('header_keywords', 'Header Keywords', 'headerKeywords')),
    entities: toArr(pick('entities', 'Entities')),
    common_keywords: toArr(pick('common_keywords', 'Common Keywords', 'commonKeywords')),
    extra_keywords: toArr(pick('extra_keywords', 'Extra Keywords', 'extraKeywords')),
    intent_context_text: String(pick('intent_context_text', 'intentContextText') || '').trim(),
    salience_context_text: String(pick('salience_context_text', 'salienceContextText') || '').trim(),
    audience_context_text: String(pick('audience_context_text', 'audienceContextText') || '').trim(),
    guardrail_id: parseInt(pick('guardrail_id', 'guardrailId')) || 0,
    _raw_form_keys: Object.keys(form)
  }
}];

// If audio was supplied, send it to OpenRouter for transcription.
// Otherwise pass the raw text through unchanged.
//
// REPLACE the OPENROUTER_API_KEY constant with your own key.
// Audio transcription model: google/gemini-2.5-flash is cheap + multimodal.
// Swap the TRANSCRIBE_MODEL below if you want a different transcription model.

const OPENROUTER_API_KEY = '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';
const TRANSCRIBE_MODEL   = 'google/gemini-2.5-flash';

const form = $('Normalize Outline Inputs').first().json;
const hasAudio = !!(form.audio_base64 && form.audio_base64.length > 100);

if (!hasAudio) {
  return [{
    json: {
      transcript: form.text || '',
      source: 'text',
      transcription_model: null
    }
  }];
}

try {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://openrouter.ai/api/v1/chat/completions',
    headers: {
      'Authorization': 'Bearer ' + OPENROUTER_API_KEY,
      'Content-Type': 'application/json',
      'HTTP-Referer': 'https://shettymarketing.com',
      'X-Title': 'Content Optimizer (n8n)'
    },
    body: {
      model: TRANSCRIBE_MODEL,
      messages: [{
        role: 'user',
        content: [
          { type: 'text', text: 'Transcribe the audio verbatim. Output only the transcribed text. Do not summarize, paraphrase, or add any preamble or formatting.' },
          { type: 'input_audio', input_audio: { data: form.audio_base64, format: form.audio_format || 'webm' } }
        ]
      }]
    },
    json: true,
    timeout: 120000
  });

  const transcript = resp?.choices?.[0]?.message?.content || '';
  if (!transcript) {
    return [{ json: { error: 'Empty transcript from OpenRouter', raw: resp } }];
  }
  return [{
    json: {
      transcript,
      source: 'audio',
      transcription_model: TRANSCRIBE_MODEL
    }
  }];
} catch (err) {
  return [{
    json: {
      error: 'Transcription failed',
      detail: String(err && err.message ? err.message : err)
    }
  }];
}

