const OPENROUTER_API_KEY = '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';
const COMPLIANCE_MODEL = 'google/gemini-2.5-flash';

const resp = $('OpenRouter (Outline)').first().json;
const payload = $('Build Outline Prompt').first().json;

const guardrails = (payload.form?.guardrail_content || '').trim();
if (!guardrails) {
  return [{ json: .first().json }];
}

const outline = resp?.choices?.[0]?.message?.content || '';
if (!outline) {
  return [{ json: resp }];
}

const cleaned = outline.replace(/`(?:markdown|md)?\\s*/i, '').replace(/\\s*`\\s*$/i, '').trim();

const systemPrompt = 'You are a compliance reviewer. Check the service-page outline against the guardrails below. If ANY section, heading, or description violates a guardrail, rewrite JUST those parts to comply. If the outline is fully compliant, return it unchanged.\\n\\nGUARDRAILS (non-negotiable):\\n' + guardrails + '\\n\\nRULES:\\n1. Every heading and section description must comply with ALL guardrails\\n2. If a section makes a banned claim, rewrite it to be compliant\\n3. If a required disclaimer is missing, add it as a note in the relevant section\\n4. Preserve the overall structure and intent of the outline\\n5. Only modify what is necessary for compliance\\n\\nOUTPUT: Return the full corrected outline in plain markdown. No preamble, no explanation, no code fences.';

try {
  const orResp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://openrouter.ai/api/v1/chat/completions',
    headers: {
      'Authorization': 'Bearer ' + OPENROUTER_API_KEY,
      'Content-Type': 'application/json',
      'HTTP-Referer': 'https://shettymarketing.com',
      'X-Title': 'Guardrails Compliance Check (n8n)'
    },
    body: {
      model: COMPLIANCE_MODEL,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: 'Check this outline for compliance:\\n\\n' + cleaned }
      ],
      temperature: 0.2,
      max_tokens: 8192
    },
    json: true,
    timeout: 60000
  });

  const result = orResp?.choices?.[0]?.message?.content || '';
  const resultCleaned = result.replace(/`(?:markdown|md)?\\s*/i, '').replace(/\\s*`\\s*$/i, '').trim();
  const changed = resultCleaned !== cleaned;

  return [{ json: { ...resp, choices: [{ message: { content: resultCleaned } }], compliance_check: { performed: true, changed: changed, guardrails_applied: payload.form?.guardrail_name || 'Unknown' } } }];
} catch (e) {
  return [{ json: { ...resp, compliance_check: { performed: true, changed: false, error: e.message } } }];
}

